"""Streamlit viewer for outputs generated by src/pipeline.py."""
from pathlib import Path
import pandas as pd
import plotly.express as px
import plotly.graph_objects as go
import streamlit as st
import networkx as nx

ROOT = Path(__file__).resolve().parent
DATA = ROOT / "data/processed"
st.set_page_config(page_title="Metformin literature signals", layout="wide")
st.markdown("""
<style>
:root { --cream: #FFEFD2; --teal: #6AB0AF; --coral: #F5A89A; --yellow: #FFF2A5; --ink: #264443; }
.stApp { background: var(--cream); color: var(--ink); }
[data-testid="stHeader"] { background: rgba(255,239,210,.92); }
[data-testid="stMetric"] { background: #fff8eb; border: 1px solid #6AB0AF; padding: 14px 16px; border-radius: 12px; }
.stButton > button, .stDownloadButton > button { background: var(--teal); color: #173b3b; border: 0; border-radius: 9px; }
div[data-baseweb="select"] > div { background: #fff8eb; border-color: var(--teal); }
</style>
""", unsafe_allow_html=True)
st.title("AI-assisted literature screening: Metformin and lactic acidosis")
st.caption("PubMed literature evidence only. This rule-based screen does not establish causality or clinical risk.")

def load(name):
    path = DATA / name
    return pd.read_csv(path, dtype={"pmid": str}).fillna("") if path.exists() else pd.DataFrame()

relations = load("drug_adr_relations.csv")
priority = load("signal_prioritization.csv")
raw = pd.read_csv(ROOT / "data/raw/raw_data.csv", dtype={"pmid": str}).fillna("") if (ROOT / "data/raw/raw_data.csv").exists() else pd.DataFrame()
if raw.empty:
    st.info("No data found yet. Set PUBMED_EMAIL and run `python -m src.pipeline` to retrieve PubMed records and build the outputs.")
else:
    if "retrieved_at_utc" in raw and not raw.retrieved_at_utc.empty:
        st.caption(f"PubMed snapshot retrieved {raw.retrieved_at_utc.iloc[0]} (UTC)")
    counts = relations.relationship_category.value_counts() if not relations.empty else pd.Series(dtype=int)
    a, b, c, d = st.columns(4)
    a.metric("PubMed records", len(raw))
    b.metric("Relationship sentences", len(relations))
    c.metric("Supportive publications", int(relations.loc[relations.relationship_category == "Supportive", "pmid"].nunique()) if not relations.empty else 0)
    d.metric("Screening priority", priority.iloc[0].priority_label if not priority.empty else "Not calculated")
    st.subheader("Evidence categories")
    if not counts.empty:
        palette = {"Supportive": "#6AB0AF", "Negated": "#F5A89A", "Uncertain": "#FFF2A5", "Co-occurrence only": "#b6a99a"}
        chart = px.bar(x=counts.index, y=counts.values, labels={"x": "Rule-based category", "y": "Sentences"}, color=counts.index, color_discrete_map=palette)
        st.plotly_chart(chart, use_container_width=True)
    else:
        st.write("No sentences containing both target entities were found.")
    # Network summarizes sentence-level categories, not causal links.
    st.subheader("Entity relationship overview")
    if not relations.empty:
        totals = relations.relationship_category.value_counts()
        G = nx.Graph()
        G.add_node("Metformin", kind="drug")
        G.add_node("Lactic acidosis", kind="ADR")
        for category, count in totals.items():
            G.add_node(category, kind="evidence")
            G.add_edge("Metformin", category, weight=int(count))
            G.add_edge(category, "Lactic acidosis", weight=int(count))
        pos = nx.spring_layout(G, seed=7)
        edge_x, edge_y = [], []
        for u, v in G.edges():
            edge_x.extend([pos[u][0], pos[v][0], None]); edge_y.extend([pos[u][1], pos[v][1], None])
        nodes = list(G.nodes())
        fig = go.Figure()
        fig.add_trace(go.Scatter(x=edge_x, y=edge_y, mode="lines", line={"width": 1, "color": "#9aa4b2"}, hoverinfo="none"))
        fig.add_trace(go.Scatter(x=[pos[n][0] for n in nodes], y=[pos[n][1] for n in nodes], mode="markers+text",
            text=nodes, textposition="top center", marker={"size": [34 if n in ("Metformin", "Lactic acidosis") else 18 for n in nodes], "color": ["#6AB0AF" if G.nodes[n]["kind"] == "drug" else "#F5A89A" if G.nodes[n]["kind"] == "ADR" else "#FFF2A5" for n in nodes]},
            hovertext=[f"{n}: {totals.get(n, 0)} sentences" for n in nodes], hoverinfo="text"))
        fig.update_layout(showlegend=False, xaxis={"visible": False}, yaxis={"visible": False}, height=400, margin={"l": 0, "r": 0, "t": 15, "b": 0})
        st.plotly_chart(fig, use_container_width=True)
    st.subheader("Sentence evidence")
    if not relations.empty:
        categories = ["All"] + sorted(relations.relationship_category.unique())
        selected = st.selectbox("Filter by category", categories)
        view = relations if selected == "All" else relations[relations.relationship_category == selected]
        st.dataframe(view, use_container_width=True, hide_index=True)
    st.subheader("FAERS reference values (provided assignment data)")
    st.caption("These supplied pharmacovigilance statistics are separate from and were not calculated by the PubMed NLP pipeline.")
    st.dataframe(pd.DataFrame([{"Reports": 408, "ROR": 499.446412, "PRR": 338.044717, "EBGM": 175.482554, "Signal label": 1}]), hide_index=True)
